function parseCsvLine(line) {
    const result = [];
    let cur = "";
    let inQuotes = false;
    for (let i = 0; i < line.length; i++) {
        const ch = line[i];
        if (inQuotes) {
            if (ch === "\"") {
                if (line[i + 1] === "\"") { cur += "\""; i++; }
                else inQuotes = false;
            } else cur += ch;
        } else {
            if (ch === "\"") inQuotes = true;
            else if (ch === ",") { result.push(cur); cur = ""; }
            else cur += ch;
        }
    }
    result.push(cur);
    return result;
}

function num(v) {
    if (v === undefined || v === null || v === "") return null;
    const n = Number(v);
    return Number.isFinite(n) ? n : null;
}

function clean(v) {
    return (v === undefined || v === null || v === "") ? null : v;
}

function getDate(v) {
    if (!v) return null;
    const d = new Date(v);
    return isNaN(d.getTime()) ? null : d;
}

function normalizeRow(p) {
    const row = { ...p };
    const start = getDate(p.conversation_start);
    const delaySeconds =
        num(p.customer_to_agent_seconds) ??
        num(p.dominant_latency_seconds) ??
        num(p.alert_to_agent_seconds) ??
        num(p.dial_to_customer_seconds);

    let delayBand = null;
    if (delaySeconds !== null) {
        if (delaySeconds < 3) delayBand = "0-2";
        else if (delaySeconds < 10) delayBand = "2-10";
        else if (delaySeconds < 20) delayBand = "10-20";
        else delayBand = "20+";
    }

    row.delay_seconds = delaySeconds;
    row.delay_band = delayBand;
    row.hour = start ? start.getHours() : null;
    row.weekday = start ? start.toLocaleDateString("en-US", { weekday: "short" }) : null;
    row.date = start ? start.toISOString().slice(0, 10) : null;
    row.disposition_name = clean(row.disposition_name);
    row.disposition_analyzer = clean(row.disposition_analyzer);
    return row;
}

const path = msg.filename;
const campaign = msg.campaign;
const MAX_BYTES = 250 * 1024 * 1024;
const MAX_ROWS = 400000;

if (!path) {
    node.warn("No filename provided");
    return null;
}

try {
    const size = fs.statSync(path).size;
    if (size > MAX_BYTES) {
        node.error(`Campaign file too large (${Math.round(size / 1024 / 1024)}MB). Max supported size is 250MB.`, msg);
        return null;
    }
} catch (err) {
    node.error("Cannot access campaign file: " + err.message, msg);
    return null;
}

node.status({ fill: "blue", shape: "dot", text: "loading..." });

return new Promise((resolve, reject) => {
    let headers = null;
    let rowCount = 0;
    let truncated = false;
    const rows = [];

    const rl = readline.createInterface({
        input: fs.createReadStream(path, { encoding: "utf8" }),
        crlfDelay: Infinity
    });

    rl.on("line", (line) => {
        if (!line) return;

        if (!headers) {
            headers = parseCsvLine(line);
            return;
        }

        rowCount++;
        if (rowCount > MAX_ROWS) {
            truncated = true;
            rl.close();
            return;
        }

        const values = parseCsvLine(line);
        const raw = {};
        headers.forEach((h, i) => { raw[h] = values[i] ?? ""; });
        rows.push(normalizeRow(raw));

        if (rowCount % 10000 === 0) {
            node.status({ fill: "blue", shape: "dot", text: rowCount + " rows..." });
        }
    });

    rl.on("close", () => {
        const text = truncated
            ? `${rows.length} rows (truncated)`
            : `${rows.length} rows loaded`;
        node.status({ fill: "green", shape: "dot", text: text });
        if (truncated) {
            node.warn(`Campaign truncated at ${MAX_ROWS} rows`);
        }
        node.send({ payload: rows, campaign: campaign });
        resolve(null);
    });

    rl.on("error", (err) => {
        node.status({ fill: "red", shape: "ring", text: "load failed" });
        reject(err);
    });
});

