    { source: "Attempts", target: "Fax", value: fax },
    { source: "Attempts", target: "Disconnect", value: disconnect },
    { source: "Attempts", target: "Error", value: error },
    { source: "Attempts", target: "Other", value: other },
    { source: "Live Voice", target: "Transferred", value: transferred },
    { source: "Live Voice", target: "Not Transferred", value: notTransferred },
    { source: "Transferred", target: "Agent Connected", value: agentConnected },
    { source: "Transferred", target: "Abandoned", value: abandoned },
    { source: "Agent Connected", target: "Conversation", value: conversation },
    { source: "Agent Connected", target: "No Conversation", value: noConversation },
    { source: "Call Screener", target: "Screener Transferred", value: screenerTransferred },
    { source: "Call Screener", target: "Screener Not Transferred", value: screenerNotTransferred },
    { source: "Screener Transferred", target: "Screener Agent Connected", value: screenerAgentConnected },
    { source: "Screener Transferred", target: "Screener Abandoned", value: screenerAbandoned },
    { source: "Screener Agent Connected", target: "Screener Conversation", value: screenerConversation },
    { source: "Screener Agent Connected", target: "Screener No Conversation", value: screenerNoConversation }
].filter((link) => link.value > 0);

const nodeNames = new Set(["Attempts"]);
links.forEach((link) => {
    nodeNames.add(link.source);
    nodeNames.add(link.target);
});

const palette = {
    "Attempts": "#0094CE",
    "No Answer": "#B0BEC5",
    "Ended Without Disposition": "#78909C",
    "Answering Machine": "#FF9896",
    "Live Voice": "#2CA02C",
    "Call Screener": "#17BECF",
    "IVR": "#AEC7E8",
    "Busy": "#FF7F0E",
    "Sit Tone": "#9467BD",
    "Fax": "#8C564B",
    "Disconnect": "#D62728",
    "Error": "#E377C2",
    "Other": "#CFCFCF",
    "Transferred": "#98DF8A",
    "Not Transferred": "#C5E1A5",
    "Agent Connected": "#1B9E77",
    "Abandoned": "#F4A261",
    "Conversation": "#006D2C",
    "No Conversation": "#A1D99B",
    "Screener Transferred": "#7FDBDA",
    "Screener Not Transferred": "#B2EBF2",
    "Screener Agent Connected": "#00897B",
    "Screener Abandoned": "#FFB74D",
    "Screener Conversation": "#004D40",
    "Screener No Conversation": "#80CBC4"
};

const nodes = [...nodeNames].map((name) => ({
    name,
    itemStyle: { color: palette[name] || "#7F7F7F" }
}));

const sankeyOption = {
    tooltip: {
        trigger: "item",
        triggerOn: "mousemove",
        formatter: (params) => {
            if (params.dataType === "edge") {
                const pct = attempts ? (100 * params.data.value / attempts).toFixed(2) : 0;
                return `${params.data.source} → ${params.data.target}<br/>${params.data.value.toLocaleString()} (${pct}% of attempts)`;
            }
            return `${params.name}<br/>${(params.value || 0).toLocaleString()}`;
        }
    },
    series: [{
        type: "sankey",
        layout: "none",
        emphasis: { focus: "adjacency" },
        nodeAlign: "left",
        lineStyle: { color: "gradient", curveness: 0.5, opacity: 0.35 },
        label: { color: "#333", fontSize: 12 },
        nodeGap: 14,
        data: nodes,
        links
    }]
};

const tableMsg = { ...msg, payload: kpiRows };
const chartMsg = { ...msg, payload: { option: sankeyOption } };

return [tableMsg, chartMsg];

const campaign = global.get("selectedCampaign");
if (!campaign) {
    node.warn("No campaign selected");
    return null;
}
msg.params = { $campaign: campaign };
return msg;

const row = Array.isArray(msg.payload) ? msg.payload[0] : msg.payload;
if (!row) {
    msg.payload = [];
    return msg;
}

const n = (v) => Number(v || 0);
const attempts = n(row.attempts);
const ivrReach = n(row.ivr_reach);
const acdOffer = n(row.acd_offer);
const agentAlerted = n(row.agent_alerted);
const agentConnected = n(row.agent_connected);
const abandonAcd = n(row.abandon_after_acd);
const abandonAlert = n(row.abandon_after_alert);
const endedWithoutDisposition = n(row.ended_without_disposition);

const num = (v) => n(v).toLocaleString();
const pctAttempts = (v) => (attempts ? (100 * n(v) / attempts).toFixed(2) + "%" : "—");
const pctPrev = (v, prev) => (prev ? (100 * n(v) / prev).toFixed(1) + "% of previous" : "—");
const sec = (v) => (v == null || v === "" ? "—" : Number(v).toFixed(2) + " sec");

msg.payload = [
    { metric: "Calls Attempted", count: num(attempts), pct_of_attempts: "100.00%", stage_conversion: "—" },
    { metric: "IVR Reach", count: num(ivrReach), pct_of_attempts: pctAttempts(ivrReach), stage_conversion: "—" },
    { metric: "ACD Offer", count: num(acdOffer), pct_of_attempts: pctAttempts(acdOffer), stage_conversion: pctPrev(acdOffer, ivrReach) },
    { metric: "Agent Alerted", count: num(agentAlerted), pct_of_attempts: pctAttempts(agentAlerted), stage_conversion: pctPrev(agentAlerted, acdOffer) },
    { metric: "Agent Connected", count: num(agentConnected), pct_of_attempts: pctAttempts(agentConnected), stage_conversion: pctPrev(agentConnected, agentAlerted) },
    { metric: "Agent Pickup Rate", count: agentAlerted ? (100 * agentConnected / agentAlerted).toFixed(1) + "%" : "—", pct_of_attempts: "—", stage_conversion: "connected ÷ alerted" },
    { metric: "Abandon After ACD Offer", count: num(abandonAcd), pct_of_attempts: pctAttempts(abandonAcd), stage_conversion: pctPrev(abandonAcd, acdOffer) },
    { metric: "Abandon After Alert", count: num(abandonAlert), pct_of_attempts: pctAttempts(abandonAlert), stage_conversion: pctPrev(abandonAlert, agentAlerted) },
    { metric: "Ended Without Disposition", count: num(endedWithoutDisposition), pct_of_attempts: pctAttempts(endedWithoutDisposition), stage_conversion: "—" },
    { metric: "Avg IVR-to-ACD", count: sec(row.avg_ivr_to_acd), pct_of_attempts: "—", stage_conversion: "n=" + num(row.n_ivr_to_acd) },
    { metric: "Avg ACD-to-Alert", count: sec(row.avg_acd_to_alert), pct_of_attempts: "—", stage_conversion: "n=" + num(row.n_acd_to_alert) },
    { metric: "Avg Alert-to-Agent", count: sec(row.avg_alert_to_agent), pct_of_attempts: "—", stage_conversion: "n=" + num(row.n_alert_to_agent) }
];
return msg;

const rows = Array.isArray(msg.payload) ? msg.payload : [];
const num = (v) => Number(v || 0).toLocaleString();

msg.payload = rows.map((row) => ({
    stage: row.stage || "Unknown",
    count: num(row.count),
    pct_of_calls: row.pct_of_calls != null ? Number(row.pct_of_calls).toFixed(2) + "%" : "—"
}));
return msg;

const campaign = global.get("selectedCampaign");
if (!campaign) {
    node.warn("No campaign selected");
    return null;
}
msg.params = { $campaign: campaign };
return msg;

const rows = Array.isArray(msg.payload) ? msg.payload : [];
if (!rows.length) {
    msg.payload = [];
    return msg;
}

const num = (v) => Number(v || 0).toLocaleString();
const attempts = Number(rows[0].total_attempts || 0);
let sumCount = 0;
let sumPct = 0;

const out = rows.map((row) => {
    const count = Number(row.count || 0);
    const pct = Number(row.pct_of_attempts || 0);
    sumCount += count;
    sumPct += pct;
    return {
        outcome: row.bucket,
        count: num(count),
        pct_of_attempts: pct.toFixed(2) + "%"
    };
});

out.push({
    outcome: "TOTAL (all buckets)",
    count: num(sumCount),
    pct_of_attempts: sumPct.toFixed(2) + "%"
});

msg.payload = out;
return msg;

const rows = Array.isArray(msg.payload) ? msg.payload : [];
const num = (v) => Number(v || 0).toLocaleString();
const pct = (v, base) => (base ? (100 * Number(v || 0) / base).toFixed(1) + "%" : "—");

msg.payload = rows.map((row) => {
    const attempts = Number(row.attempts || 0);
    const contacts = Number(row.contacts || 0);
    const transferred = Number(row.transferred || 0);
    const connected = Number(row.agent_connected || 0);
    return {
        path: row.path,
        contacts: num(contacts),
        pct_of_attempts: pct(contacts, attempts),
        transferred: num(transferred),
        transfer_rate: pct(transferred, contacts),
        agent_connected: num(connected),
        pickup_rate: pct(connected, transferred)
    };
});
return msg;

const rows = Array.isArray(msg.payload) ? msg.payload : [];
const num = (v) => Number(v || 0).toLocaleString();
const pct = (v, base) => (base ? (100 * Number(v || 0) / base).toFixed(2) + "%" : "—");

msg.payload = rows.map((row) => ({
    loss_point: row.loss_point,
    count: num(row.count),
    pct_of_prior_stage: pct(row.count, row.prior_count),
    prior_stage: row.prior_stage + " (" + num(row.prior_count) + ")",
    top_disposition: row.top_disposition || "—"
}));
return msg;

const rows = Array.isArray(msg.payload) ? msg.payload : [];
const num = (v) => Number(v || 0).toLocaleString();

msg.payload = rows.map((row) => {
    const isBand = row.section === "Delay Band";
    let value = "—";
    if (row.pct != null) {
        if (isBand) {
            value = Number(row.pct).toFixed(2) + "%";
        } else if (String(row.metric).includes("(sec)")) {
            value = Number(row.pct).toFixed(2) + " sec";
        } else if (String(row.metric).startsWith("Pct")) {
            value = Number(row.pct).toFixed(2) + "%";
        } else {
            value = String(row.pct);
        }
    }
    return {
        section: row.section,
        metric: row.metric,
        count: isBand ? num(row.count) : "—",
        pct_or_value: value,
        notes: row.detail || "—"
    };
});
return msg;

const rows = Array.isArray(msg.payload) ? msg.payload : [];
const num = (v) => Number(v || 0).toLocaleString();

msg.options = rows.map((row) => ({
    label: row.name + " (" + num(row.row_count) + ")",
    value: row.id,
    type: "str"
}));

if (!msg.options.length) {
    node.warn("No campaigns found in database — run scripts/import_campaigns.py");
}

return msg;

const campaign = global.get("selectedCampaign");
if (!campaign) {
    node.warn("No campaign selected");
    return null;
}
msg.params = { $campaign: campaign };
return msg;

const row = Array.isArray(msg.payload) ? msg.payload[0] : msg.payload;
const dash = "—";
const pct = (v) => (v == null || v === "" ? dash : Number(v).toFixed(2) + "%");
const sec = (v) => (v == null || v === "" ? dash : Number(v).toFixed(3) + " sec");
const num = (v) => (v == null || v === "" ? dash : Number(v).toLocaleString());
const empty = { title: "—", metrics: [] };

if (!row) {
    return [{ payload: empty }, { payload: empty }, { payload: empty }, { payload: empty }];
}

const original = {
    title: "Latency & Volume",
    metrics: [
        { label: "Interactions Evaluated", value: num(row.interactions) },
        { label: "Average Customer→Speech", value: sec(row.avg_customer_to_speech) },
        { label: "Average Disposition→Agent", value: sec(row.avg_disposition_to_agent) },
        { label: "P95 Disposition→Agent", value: sec(row.p95_disposition_to_agent) },
        { label: "P99 Disposition→Agent", value: sec(row.p99_disposition_to_agent) },
        { label: "Average Conversation Duration", value: sec(row.avg_conversation_duration) }
    ]
};

const tier1 = {
    title: "Contact Effectiveness",
    metrics: [
        { label: "Connect Rate", value: pct(row.connect_rate) },
        { label: "Right-Party Contact", value: pct(row.rpc_rate) },
        { label: "Agent Connect Rate", value: pct(row.agent_connect_rate) },
        { label: "Machine Rate", value: pct(row.machine_rate) },
        { label: "No Answer Rate", value: pct(row.no_answer_rate) },
        { label: "Ended Without Disposition", value: pct(row.ended_without_disposition_rate) },
        { label: "Ended w/o Disp Avg Connected", value: sec(row.avg_ended_without_disposition_connected) },
        { label: "Ended w/o Disp P90 Connected", value: sec(row.p90_ended_without_disposition_connected) },
        { label: "Ended w/o Disp P95 Connected", value: sec(row.p95_ended_without_disposition_connected) },
        { label: "Ended w/o Disp P99 Connected", value: sec(row.p99_ended_without_disposition_connected) },
        { label: "Conversation ≥30s", value: pct(row.conversation_30s_rate) },
        { label: "Call Screener Rate", value: pct(row.call_screener_rate) }
    ]
};

const tier2 = {
    title: "Routing & Quality",
    metrics: [
        { label: "Transfer Rate", value: pct(row.transfer_rate) },
        { label: "Agent Pickup Rate", value: pct(row.agent_pickup_rate) },
        { label: "Abandon After ACD", value: pct(row.abandon_acd_rate) },
        { label: "Conversation ≥2min", value: pct(row.conversation_2min_rate) }
    ]
};

const tier3 = {
    title: "Compliance & Timing",
    metrics: [
        { label: "0–2 sec Compliance (Disp→Agent)", value: pct(row.pct_delay_0_2) },
        { label: "Avg Dial-to-Customer", value: sec(row.avg_dial_to_customer) },
        { label: "P95 Disposition→Agent", value: sec(row.p95_disposition_to_agent) },
        { label: "P99 Disposition→Agent", value: sec(row.p99_disposition_to_agent) },
        { label: "Conference Rate", value: pct(row.conference_rate) }
    ]
};

return [
    { payload: original },
    { payload: tier1 },
    { payload: tier2 },
    { payload: tier3 }
];

const campaign = global.get("selectedCampaign");
if (!campaign) {
    node.warn("No campaign selected");
    return null;
}
msg.params = { $campaign: campaign };
return msg;

const SERIES = [
    { key: "avg_seconds", label: "Average" },
    { key: "p95_seconds", label: "P95" },
    { key: "p99_seconds", label: "P99" }
];

const rows = msg.payload || [];
const out = [];
for (const row of rows) {
    for (const s of SERIES) {
        const value = row[s.key];
        if (value == null || value === "") continue;
        out.push({
            date: row.date,
            series: s.label,
            seconds: Number(value)
        });
    }
}
msg.payload = out;
return msg;

const campaign = global.get("selectedCampaign");
if (!campaign) {
    node.warn("No campaign selected");
    return null;
}
msg.params = { $campaign: campaign };
return msg;

const SERIES = [
    //{ key: "dials", label: "Dials" },
    { key: "speech_person", label: "Live Voice (speech.person)" },
    { key: "call_screener", label: "Call Screener (IVR path)" }
];

const rows = msg.payload || [];
const out = [];
for (const row of rows) {
    for (const s of SERIES) {
        out.push({
            date: row.date,
            series: s.label,
            count: Number(row[s.key] || 0)
        });
    }
}
msg.payload = out;
return msg;

const campaign = global.get("selectedCampaign");
if (!campaign) {
    node.warn("No campaign selected");
    return null;
}
msg.params = { $campaign: campaign };
return msg;

const row = Array.isArray(msg.payload) ? msg.payload[0] : msg.payload;
const dash = "—";

function parseSummary(raw) {
    if (!raw) return null;
    if (typeof raw === "object") return raw;
    try {
        return JSON.parse(raw);
    } catch (err) {
        return null;
    }
}

function latestEntry(list) {
    if (!Array.isArray(list) || !list.length) return null;
    return list[list.length - 1];
}

function uniqueStates(list) {
    if (!Array.isArray(list)) return [];
    const seen = new Set();
    const out = [];
    for (const item of list) {
        const state = item && item.state;
        if (!state || seen.has(state)) continue;
        seen.add(state);
        out.push(state);
    }
    return out;
}

if (!row) {
    msg.payload = {
        title: "Genesys Dialer Diagnostics",
        subtitle: "No diagnostic summary loaded for this campaign",
        healthState: dash,
        campaignState: dash,
        fetchedAt: dash,
        metrics: []
    };
    return msg;
}

const summary = parseSummary(row.summary_json);
const metrics = [];
const push = (label, value) => {
    const text = value == null || value === "" ? dash : String(value);
    metrics.push({ label, value: text });
};

const latestCampaign = latestEntry(summary && summary.campaignStates);
const latestHealth = latestEntry(summary && summary.campaignHealthStates);
const healthStates = uniqueStates(summary && summary.campaignHealthStates);
const healthState = row.health_state || (latestHealth && latestHealth.state) || dash;
const campaignState = row.campaign_state || (latestCampaign && latestCampaign.state) || dash;

push("Campaign", row.campaign_name || row.campaign_id);
push("Interval", summary ? `${summary.dateStart || dash} → ${summary.dateEnd || dash}` : dash);
push("Dialing Mode", latestCampaign && latestCampaign.dialingMode);
push("Campaign State", campaignState);
push("Latest Health", healthState);
push("Health States Seen", healthStates.length ? healthStates.join(", ") : dash);
push("Health Events", summary && summary.campaignHealthStates ? summary.campaignHealthStates.length : dash);
push("State Changes", summary && summary.campaignStates ? summary.campaignStates.length : dash);
push("Config Changes", summary && summary.configChanges ? summary.configChanges.length : dash);
push("Imported Rows", row.row_count != null ? Number(row.row_count).toLocaleString() : dash);
push("Fetched At", row.fetched_at);

msg.payload = {
    title: "Genesys Dialer Diagnostics",
    subtitle: "June 2026 dialer health timeline from Genesys diagnostics summary API",
    healthState,
    campaignState,
    fetchedAt: row.fetched_at || dash,
    metrics
};
return msg;

