const n = (v) => {
    const x = Number(v);
    return Number.isFinite(x) ? x : 0;
};

const allStageDefs = [
    {
        key: "connect_to_speech_start",
        label: "Connect \u2192 Speech start",
        short: "Customer connect to speech detection start",
        field: "avg_connect_to_speech_start",
        color: "#7BA7F7",
        onTimeline: false,
        leadIn: true
    },
    {
        key: "speech_start_to_disposition",
        label: "Speech start \u2192 Disposition",
        short: "Speech detection start to speech.person (detectedSpeechEnd)",
        field: "avg_speech_start_to_disposition",
        color: "#5B8DEF",
        onTimeline: false,
        leadIn: true
    },
    {
        key: "disposition_to_ivr",
        label: "Disposition \u2192 IVR",
        short: "speech.person disposition to IVR start",
        field: "avg_disposition_to_ivr",
        color: "#2A60C8",
        onTimeline: true
    },
    {
        key: "ivr_to_queue",
        label: "IVR \u2192 Queue",
        short: "IVR start to queue offer",
        field: "avg_ivr_to_queue",
        color: "#1E4A9A",
        onTimeline: true
    },
    {
        key: "queue_to_alert",
        label: "Queue \u2192 Alert",
        short: "Queue offer to agent alert",
        field: "avg_queue_to_alert",
        color: "#E07A2F",
        onTimeline: true
    },
    {
        key: "alert_to_agent",
        label: "Alert \u2192 Agent",
        short: "Agent alert to agent connected",
        field: "avg_alert_to_agent",
        color: "#2CA02C",
        onTimeline: true
    }
];

const p90FieldByKey = {
    connect_to_speech_start: "p90_connect_to_speech_start",
    speech_start_to_disposition: "p90_speech_start_to_disposition",
    disposition_to_ivr: "p90_disposition_to_ivr",
    ivr_to_queue: "p90_ivr_to_queue",
    queue_to_alert: "p90_queue_to_alert",
    alert_to_agent: "p90_alert_to_agent"
};

const callCount = n(row.call_count);
const avgTotal = n(row.avg_total);

const allStages = allStageDefs.map((def) => {
    const avg = n(row[def.field]);
    const pct = avgTotal > 0 ? ((100 * avg) / avgTotal).toFixed(1) : "0.0";
    return {
        key: def.key,
        label: def.label,
        short: def.short,
        color: def.color,
        avg,
        p90: n(row[p90FieldByKey[def.key]]),
        pct,
        onTimeline: def.onTimeline
    };
});

const leadInStageDefs = allStageDefs.filter((d) => d.leadIn);
let leadInOffset = 0;
const leadInStages = leadInStageDefs.map((def) => {
    const avg = n(row[def.field]);
    const start = leadInOffset;
    const end = leadInOffset + avg;
    leadInOffset = end;
    const pct = avgTotal > 0 ? ((100 * avg) / avgTotal).toFixed(1) : "0.0";
    return {
        key: def.key,
        label: def.label,
        short: def.short,
        color: def.color,
        avg,
        start,
        end,
        pct,
        pctLeadIn: "0.0"
    };
});

const avgLeadIn = leadInOffset;
leadInStages.forEach((stage) => {
    stage.pctLeadIn = avgLeadIn > 0
        ? ((100 * stage.avg) / avgLeadIn).toFixed(1)
        : "0.0";
});

const leadInMilestones = [
    { label: "Customer connect", at: 0 },
    { label: "Speech start", at: leadInStages[0] ? leadInStages[0].end : 0 },
    { label: "Disposition (speech.person)", at: avgLeadIn }
];

const timelineStageDefs = allStageDefs.filter((d) => d.onTimeline);

let offset = 0;
const stages = timelineStageDefs.map((def) => {
    const avg = n(row[def.field]);
    const start = offset;
    const end = offset + avg;
    offset = end;
    const pctTotal = avgTotal > 0 ? ((100 * avg) / avgTotal).toFixed(1) : "0.0";
    return {
        key: def.key,
        label: def.label,
        short: def.short,
        color: def.color,
        avg,
        start,
        end,
        pct: pctTotal,
        pctPost: "0.0"
    };
});

const avgPostDisposition = offset;
stages.forEach((stage) => {
    stage.pctPost = avgPostDisposition > 0
        ? ((100 * stage.avg) / avgPostDisposition).toFixed(1)
        : "0.0";
});

const milestones = [
    { label: "Disposition (speech.person)", at: 0 },
    { label: "IVR start", at: stages[0] ? stages[0].end : 0 },
    { label: "Queue offer", at: stages[1] ? stages[1].end : 0 },
    { label: "Agent alert", at: stages[2] ? stages[2].end : 0 },
    { label: "Agent connected", at: stages[3] ? stages[3].end : avgPostDisposition }
];


const boundaries = [
    {
        at: 0,
        key: "customer_connected_time",
        label: "Customer connect",
        field: "customer_connected_time",
        description: "Pre-disposition lead-in begins here"
    }
];

if (leadInStages[0]) {
    boundaries.push({
        at: leadInStages[0].end,
        key: "speech_detected_start",
        label: "Speech start",
        field: "speech_detected_start",
        description: "detectedSpeechStart — AMD begins analyzing live speech"
    });
}

boundaries.push({
    at: avgLeadIn,
    key: "speech_detected_end",
    label: "Disposition (speech.person)",
    field: "speech_detected_end",
    description: "detectedSpeechEnd — lead-in ends and post-disposition timeline starts (same instant, no overlap)",
    isOrigin: true
});

const postBoundaryDefs = [
    { key: "ivr_start_time", label: "IVR start", field: "ivr_start_time", stageIdx: 0 },
    { key: "acd_offer_time", label: "Queue offer", field: "acd_offer_time", stageIdx: 1 },
    { key: "agent_alert_time", label: "Agent alert", field: "agent_alert_time", stageIdx: 2 },
    { key: "agent_connected_time", label: "Agent connected", field: "agent_connected_time", stageIdx: 3 }
];

postBoundaryDefs.forEach((def) => {
    const stage = stages[def.stageIdx];
    if (!stage) return;
    boundaries.push({
        at: avgLeadIn + stage.end,
        key: def.key,
        label: def.label,
        field: def.field,
        description: def.field + " — end of \"" + stage.label + "\" segment"
    });
});

const segmentAnnotations = leadInStages.map((stage) => ({
    kind: "pre",
    key: stage.key,
    label: stage.key === "speech_start_to_disposition" ? "Speech detection window" : stage.label,
    description: stage.key === "speech_start_to_disposition"
        ? "speech_detected_start → speech_detected_end. AMD classification time; counted once, not repeated on post-disposition timeline."
        : stage.short,
    color: stage.color,
    start: stage.start,
    end: stage.end,
    duration: stage.avg,
    p90: n(row[p90FieldByKey[stage.key]])
}));

stages.forEach((stage, idx) => {
    segmentAnnotations.push({
        kind: "post",
        key: stage.key,
        label: stage.label,
        description: idx === 0
            ? "speech_detected_end → ivr_start_time. Time to reach IVR after disposition is confirmed; starts after the speech detection window ends."
            : stage.short,
        color: stage.color,
        start: avgLeadIn + stage.start,
        end: avgLeadIn + stage.end,
        duration: stage.avg,
        p90: n(row[p90FieldByKey[stage.key]])
    });
});

const maxX = Math.max(avgPostDisposition, 0.5) * 1.06 || 1;
const boundaryScale = Math.max(avgTotal, 0.5) * 1.02 || 1;

msg.payload = {
    meta: {
        callCount,
        avgTotal,
        avgPostDisposition,
        avgLeadIn,
        avgConnectToDisposition: avgLeadIn,
        avgDispositionToAgent: avgPostDisposition,
        leadInStages,
        leadInMilestones,
        allStages,
        stages,
        milestones,
        boundaries,
        segmentAnnotations,
        boundaryScale,
        maxX,
        filterNote: "Pre-disposition lead-in shows connect through speech.person; main timeline starts at disposition"
    }
};
return msg;

const GENESYS_CONV_BASE = "https://apps.usw2.pure.cloud/directory/#/analytics/interactions/";

function escHtml(s) {
    return String(s)
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;");
}

function genesysConversationLink(id) {
    if (id == null || id === "") return id;
    const text = String(id).trim();
    if (!text) return id;
    const href = GENESYS_CONV_BASE + encodeURIComponent(text) + "/admin/details";
    return `<a href="${escHtml(href)}" target="_blank" rel="noopener noreferrer">${escHtml(text)}</a>`;
}

const rows = Array.isArray(msg.payload) ? msg.payload : (msg.payload ? [msg.payload] : []);
msg.payload = rows.map((row) => {
    if (!row || typeof row !== "object" || Array.isArray(row)) return row;
    if (!Object.prototype.hasOwnProperty.call(row, "conversation_id")) return row;
    return { ...row, conversation_id: genesysConversationLink(row.conversation_id) };
});
return msg;

